const raw = ($json.text || '').replace(/\r/g, '');
if (raw.trim().length < 500) {
  throw new Error('No extractable text. Scanned PDF? OCR it first.');
}

const form = $('RFP Intake').first().json;
const text = raw.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

const windows = [];
let cur = [], count = 0;
for (const line of text.split('\n')) {
  const w = line.split(/\s+/).filter(Boolean).length;
  if (count + w > 900 && cur.length) {
    windows.push(cur.join('\n'));
    cur = cur.slice(-8);
    count = cur.join(' ').split(/\s+/).length;
  }
  cur.push(line);
  count += w;
}
if (cur.length) windows.push(cur.join('\n'));

return [{ json: {
  title: form['RFP title'] || 'Untitled RFP',
  override: form['Override'] === 'Yes',
  head: windows.slice(0, 2).join('\n'),
  windows,
  full_text: text
}}];

const PROFILE = {
  regions: ['philippines', 'united kingdom', 'uk', 'remote'],
  currency: 'USD',
  min_value: 5000,
  max_value: 250000,
  certifications: ['27001'],   // one keyword per cert you actually hold
  max_years: 5,
  min_days: 7,
  bid_threshold: 55
};

const ctx = $('Clean and window').first().json;
const rfpId = $('Save RFP').first().json.id;

const msg = ($json.output || []).find(o => o.type === 'message');
const raw = msg?.content?.[0]?.text ?? $json.message?.content ?? $json.content ?? '';

let m = null;
try {
  m = typeof raw === 'string' ? JSON.parse(raw.replace(/```json|```/g, '').trim()) : raw;
} catch (e) {}

let score = 50;
const reasons = [];
if (!m) { m = {}; reasons.push('metadata unparseable, score is a guess'); }

const d = m.deadline ? new Date(m.deadline) : null;
const validDate = d && !isNaN(d);
if (validDate) {
  const days = Math.ceil((d - Date.now()) / 86400000);
  if (days < 0)                     { score -= 100; reasons.push('deadline already passed'); }
  else if (days < PROFILE.min_days) { score -= 25;  reasons.push(`only ${days} days left`); }
  else                              { score += 10;  reasons.push(`${days} days to deadline`); }
} else {
  reasons.push('deadline not found, check manually');
}

if (m.region) {
  const ok = PROFILE.regions.some(r => m.region.toLowerCase().includes(r));
  score += ok ? 15 : -25;
  reasons.push(ok ? 'region match' : `region outside coverage (${m.region})`);
}

if (m.contract_value && m.currency === PROFILE.currency) {
  const ok = m.contract_value >= PROFILE.min_value && m.contract_value <= PROFILE.max_value;
  score += ok ? 15 : -20;
  reasons.push(ok ? 'value in target range' : `value out of range (${m.contract_value})`);
}

const missing = (m.mandatory_certifications || [])
  .filter(c => !PROFILE.certifications.some(h => String(c).toLowerCase().includes(h)));
if (missing.length) { score -= 30; reasons.push('missing mandatory certs: ' + missing.join(', ')); }

if (m.required_experience_years > PROFILE.max_years) {
  score -= 10; reasons.push(`asks for ${m.required_experience_years} yrs experience`);
}

score = Math.max(0, Math.min(100, score));
const bid = score >= PROFILE.bid_threshold || ctx.override;

return [{ json: {
  rfp_id: rfpId,
  title: ctx.title,
  issuer: m.issuer ?? null,
  deadline: validDate ? String(m.deadline).slice(0, 10) : null,
  score,
  reasons: reasons.join('; '),
  bid,
  windows: ctx.windows
}}];

