const msg = ($json.output || []).find(o => o.type === 'message');
const raw = msg?.content?.[0]?.text ?? $json.message?.content ?? $json.content ?? '';
const clean = String(raw).replace(/```json|```/g, '').trim();

const KEYS = 'items|q_number|question|mandatory|category';
const repair = s => s
  .replace(/[\u0000-\u001F]+/g, ' ')                                    // raw line breaks
  .replace(new RegExp('([{,]\\s*)(' + KEYS + ')\\s*:', 'g'), '$1"$2":') // unquoted keys
  .replace(/,\s*([}\]])/g, '$1');                                        // trailing commas

const tryParse = s => { try { return JSON.parse(s); } catch (e) { return null; } };

const p = tryParse(clean) || tryParse(repair(clean));
let items = Array.isArray(p?.items) ? p.items : [];
let salvaged = false;

if (!items.length) {
  // last resort: parse each {...} object on its own
  for (const o of (clean.match(/\{[^{}]*\}/g) || [])) {
    const q = tryParse(o) || tryParse(repair(o));
    if (q && q.question) items.push(q);
  }
  salvaged = items.length > 0;
}

return [{ json: {
  items,
  count: items.length,
  salvaged,
  parse_failed: items.length === 0,
  q_numbers: items.map(i => i.q_number).join(', '),
  raw_preview: items.length ? '' : clean.slice(0, 400)
}}];

const rfpId = $('Score bid').first().json.rfp_id;
const CATS = ['COMPANY','TECHNICAL','SECURITY','PRICING','EXPERIENCE','COMPLIANCE','LEGAL','OTHER'];
const seen = new Set();
const out = [];

for (const it of $input.all()) {
  for (const q of it.json.items || []) {
    const text = (q.question || '').trim();
    if (text.length < 15) continue;
    const key = q.q_number ? 'n:' + q.q_number : 't:' + text.toLowerCase().slice(0, 60);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ json: {
      rfp_id: rfpId,
      q_number: q.q_number ?? null,
      question: text,
      mandatory: q.mandatory === true,
      category: CATS.includes(q.category) ? q.category : 'OTHER'
    }});
  }
}

if (out.length === 0) throw new Error('No requirements extracted. Check the PDF text and the extraction prompt.');
return out;

const THRESHOLD = 0.60;   // we will calibrate this with the trap questions
const q = $('Loop Over Items1').first().json;

const rows = $input.all().map(i => i.json).filter(r => r.id);
const top = rows.length ? Number(rows[0].similarity) : 0;
const usable = rows.filter(r => Number(r.similarity) >= THRESHOLD);

const context = usable
  .map(r => `[SOURCE ${r.id}] (${r.source} / ${r.section})\n${r.content}`)
  .join('\n\n');

return [{ json: {
  ...q,
  top_similarity: top,
  has_evidence: usable.length > 0,
  source_ids: usable.map(r => Number(r.id)),
  sims: rows.map(r => `${r.source}: ${r.similarity}`).join(' | '),
  context
}}];

const src = $('Build context').first().json;
const msg = ($json.output || []).find(o => o.type === 'message');
const raw = msg?.content?.[0]?.text ?? $json.message?.content ?? $json.content ?? '';
const clean = String(raw).replace(/```json|```/g, '').trim();

const KEYS = 'answer|used_sources|complete';
const repair = s => s
  .replace(/[\u0000-\u001F]+/g, ' ')
  .replace(new RegExp('([{,]\\s*)(' + KEYS + ')\\s*:', 'g'), '$1"$2":')
  .replace(/,\s*([}\]])/g, '$1');
const tryParse = s => { try { return JSON.parse(s); } catch (e) { return null; } };

const p = tryParse(clean) || tryParse(repair(clean));
if (!p) {
  return [{ json: { ...src, draft_answer: clean.slice(0, 1500), used_sources: [], status: 'needs_human', fail: 'unparseable' } }];
}

// if the model returned an object instead of text, keep it visible as text so it fails the prose check
const rawAnswer = typeof p.answer === 'string' ? p.answer : JSON.stringify(p.answer ?? '');

// strip inline "(SOURCE 3)" tags the model sometimes leaves in the text
const answer = rawAnswer
  .replace(/\s*\(?\s*SOURCES?\s*\d+(\s*,\s*\d+)*\s*\)?/gi, '')
  .replace(/\s+([.,])/g, '$1')
  .trim();

if (answer === 'INSUFFICIENT_EVIDENCE') {
  return [{ json: { ...src, draft_answer: '', used_sources: [], status: 'needs_human', fail: 'model_found_no_evidence' } }];
}

const words = answer.split(/\s+/).length;
const ctxLower = src.context.toLowerCase();
const ctxNoCommas = src.context.replace(/(\d),(?=\d)/g, '$1');

// 1) every number, year, or percentage must exist in the sources
//    (commas ignored, and "item 2.1" style references skipped)
const answerForNums = answer.replace(/\b(?:items?|questions?|sections?|requirements?)\s+\d+(?:\.\d+)*/gi, '');
const nums = (answerForNums.match(/\d[\d,.]*%?/g) || [])
  .map(n => n.replace(/[.,]+$/, '').replace(/(\d),(?=\d)/g, '$1'))
  .filter(n => n.length >= 2);
const ungrounded = nums.filter(n => !ctxNoCommas.includes(n));

// 2) every capitalised word in the middle of a sentence must exist in the sources
const IGNORE = new Set(['We', 'Our', 'The', 'This', 'These', 'Their', 'It', 'Its',
                        'Kestrel', 'Digital', 'Solutions', 'Inc']);   // your own company name
const names = new Set();
for (const s of answer.split(/(?<=[.!?])\s+/)) {
  for (const t of s.trim().split(/\s+/).slice(1)) {
    const w = t.replace(/^[^A-Za-z]+|[^A-Za-z0-9]+$/g, '');
    if (/^[A-Z][A-Za-z0-9]+$/.test(w) && !IGNORE.has(w)) names.add(w);
  }
}
const unknownNames = [...names].filter(w => !ctxLower.includes(w.toLowerCase()));

const used = Array.isArray(p.used_sources) ? p.used_sources.map(Number) : [];
const ph = answer.match(/\[.*?\]|\{\{.*?\}\}|XYZ|Lorem|TBD/i);

const checks = {
  hasAnswer:       answer.length > 40,
  isProse:         !/^\s*[\[{]/.test(answer) && !/"[A-Za-z_ ]+"\s*:/.test(answer),
  lengthOk:        words >= 25 && words <= 250,
  numbersGrounded: ungrounded.length === 0,
  namesGrounded:   unknownNames.length === 0,
  citesValid:      used.length > 0 && used.every(id => src.source_ids.includes(id)),
  noPlaceholders:  !ph,
  noAiTells:       !/as an AI|the provided sources|based on the sources/i.test(answer)
};
const failed = Object.entries(checks).filter(([, v]) => !v).map(([k]) => k);

return [{ json: {
  ...src,
  draft_answer: answer,
  used_sources: used,
  status: failed.length ? 'needs_human' : (p.complete === false ? 'partial' : 'drafted'),
  fail: failed.join(',')
    + (ph ? ` <${ph[0]}>` : '')
    + (ungrounded.length ? ` [${ungrounded.join(' ')}]` : '')
    + (unknownNames.length ? ` {${unknownNames.join(' ')}}` : '')
}}];

const rows = $input.all().map(i => i.json);
const esc = v => `"${String(v ?? '').replace(/"/g, '""').replace(/\r?\n/g, ' ')}"`;

const header = ['Ref','Category','Mandatory','Requirement','Status','Similarity','Sources','Draft answer','Flag'];
const lines = rows.map(r => [
  r.q_number,
  r.category,
  r.mandatory ? 'YES' : 'no',
  r.question,
  r.status,
  r.top_similarity ?? '',
  r.sources ?? '',
  r.draft_answer ?? '',
  r.fail ?? ''
].map(esc).join(','));

const open = rows.filter(r => r.mandatory && r.status !== 'drafted');
const dl = rows[0]?.deadline ? String(rows[0].deadline).slice(0, 10) : 'not found';

return [{ json: {
  title: rows[0]?.title,
  deadline: dl,
  total: rows.length,
  drafted: rows.filter(r => r.status === 'drafted').length,
  partial: rows.filter(r => r.status === 'partial').length,
  human: rows.filter(r => r.status === 'needs_human').length,
  mandatory_open: open.length,
  mandatory_open_refs: open.map(r => r.q_number || '?').join(', '),
  csv: '\uFEFF' + [header.join(','), ...lines].join('\n')
}}];

