const f = $('Seed Form').first().json;
const source = f['Document name'] || 'unnamed';
const section = f['Section'] || 'general';
const text = ($json.text || $json.data || '').replace(/\r/g, '');

const paras = text.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
const chunks = [];
let cur = [], words = 0;

for (const p of paras) {
  const w = p.split(/\s+/).length;
  if (words + w > 180 && cur.length) {
    chunks.push(cur.join('\n\n'));
    cur = [cur[cur.length - 1]];
    words = cur[0].split(/\s+/).length;
  }
  cur.push(p);
  words += w;
}
if (cur.length) chunks.push(cur.join('\n\n'));

return chunks.map((content, i) => ({ json: { source, section, chunk_index: i, content } }));

const chunks = $('Chunk').all();

return $input.all().map((item, i) => {
  const vec = item.json.data[0].embedding;
  if (vec.length !== 768) {
    throw new Error('Expected 768 dimensions, got ' + vec.length);
  }
  return {
    json: {
      ...chunks[i].json,
      embedding: '[' + vec.join(',') + ']'
    }
  };
});

parameters.query:
INSERT INTO library_chunks (source, section, content, content_hash, embedding)
VALUES ($1, $2, $3, md5($3::text), $4::vector)
ON CONFLICT (content_hash) DO NOTHING;
